pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title EggNFT
 * @notice ERC-721 contract for fish eggs
 * @dev Eggs can be incubated and hatched into fish
 */
contract EggNFT is ERC721, ERC721Enumerable, Ownable {
    // ============ Constants ============
    uint256 public constant INCUBATION_DURATION = 1 days;

    // ============ State ============
    uint256 private _nextTokenId;
    address public gameContract;

    struct EggInfo {
        uint256 mintedAt;
        uint256 incubationStartedAt;
        bool isIncubating;
    }

    mapping(uint256 => EggInfo) public eggs;

    // ============ Events ============
    event EggMinted(address indexed owner, uint256 indexed tokenId);
    event IncubationStarted(uint256 indexed tokenId, uint256 startTime);
    event EggHatched(uint256 indexed tokenId);

    // ============ Modifiers ============
    modifier onlyGameContract() {
        require(msg.sender == gameContract, "Only game contract");
        _;
    }

    // ============ Constructor ============
    constructor() ERC721("FryReef Egg", "FRYEGG") Ownable(msg.sender) {}

    // ============ Admin ============

    /**
     * @notice Set the game contract address
     */
    function setGameContract(address _gameContract) external onlyOwner {
        gameContract = _gameContract;
    }

    // ============ Minting ============

    /**
     * @notice Mint a new egg
     * @param _to Address to mint to
     * @return tokenId The minted token ID
     */
    function mint(address _to) external onlyGameContract returns (uint256) {
        uint256 tokenId = _nextTokenId++;
        _safeMint(_to, tokenId);

        eggs[tokenId] = EggInfo({
            mintedAt: block.timestamp,
            incubationStartedAt: 0,
            isIncubating: false
        });

        emit EggMinted(_to, tokenId);
        return tokenId;
    }

    // ============ Incubation ============

    /**
     * @notice Start incubating an egg
     * @param _tokenId The egg token ID
     */
    function startIncubation(uint256 _tokenId) external onlyGameContract {
        require(_exists(_tokenId), "Egg does not exist");
        require(!eggs[_tokenId].isIncubating, "Already incubating");

        eggs[_tokenId].isIncubating = true;
        eggs[_tokenId].incubationStartedAt = block.timestamp;

        emit IncubationStarted(_tokenId, block.timestamp);
    }

    /**
     * @notice Check if egg can be hatched
     * @param _tokenId The egg token ID
     */
    function canHatch(uint256 _tokenId) external view returns (bool) {
        if (!_exists(_tokenId)) return false;
        EggInfo storage egg = eggs[_tokenId];
        if (!egg.isIncubating) return false;
        return block.timestamp >= egg.incubationStartedAt + INCUBATION_DURATION;
    }

    /**
     * @notice Get time remaining until hatch (in seconds)
     * @param _tokenId The egg token ID
     */
    function getTimeUntilHatch(uint256 _tokenId) external view returns (uint256) {
        require(_exists(_tokenId), "Egg does not exist");
        EggInfo storage egg = eggs[_tokenId];
        if (!egg.isIncubating) return type(uint256).max;
        
        uint256 hatchTime = egg.incubationStartedAt + INCUBATION_DURATION;
        if (block.timestamp >= hatchTime) return 0;
        return hatchTime - block.timestamp;
    }

    /**
     * @notice Get egg info
     * @param _tokenId The egg token ID
     */
    function getEggInfo(uint256 _tokenId) external view returns (EggInfo memory) {
        require(_exists(_tokenId), "Egg does not exist");
        return eggs[_tokenId];
    }

    // ============ Burning ============

    /**
     * @notice Burn an egg (when hatching)
     * @param _tokenId The egg token ID
     */
    function burn(uint256 _tokenId) external onlyGameContract {
        require(_exists(_tokenId), "Egg does not exist");
        _burn(_tokenId);
        delete eggs[_tokenId];
        emit EggHatched(_tokenId);
    }

    // ============ Internal ============

    function _exists(uint256 tokenId) internal view returns (bool) {
        return _ownerOf(tokenId) != address(0);
    }

    // ============ Overrides ============

    function _update(address to, uint256 tokenId, address auth)
        internal
        override(ERC721, ERC721Enumerable)
        returns (address)
    {
        return super._update(to, tokenId, auth);
    }

    function _increaseBalance(address account, uint128 value)
        internal
        override(ERC721, ERC721Enumerable)
    {
        super._increaseBalance(account, value);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721Enumerable)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

","keccak256":"0x7ee1f25d8f6953b99cb5f59ac9fcbfc5aa9da024bdb5ad1785b327a3ef9ed916","license":"MIT"},"contracts/FishNFT.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title FishNFT
 * @notice ERC-721 contract for fish
 * @dev Fish produce Spawn Dust over time based on rarity
 */
contract FishNFT is ERC721, ERC721Enumerable, Ownable {
    // ============ Enums ============
    enum Rarity { Common, Rare, Epic, Legendary, Mythic }

    // ============ Constants ============
    // Spawn Dust per day by rarity (scaled by 1e18 for precision)
    uint256 public constant COMMON_DUST_PER_DAY = 6;
    uint256 public constant RARE_DUST_PER_DAY = 12;
    uint256 public constant EPIC_DUST_PER_DAY = 18;
    uint256 public constant LEGENDARY_DUST_PER_DAY = 32;
    uint256 public constant MYTHIC_DUST_PER_DAY = 48;

    // Rarity chances (out of 100)
    uint256 public constant COMMON_CHANCE = 50;      // 50%
    uint256 public constant RARE_CHANCE = 28;        // 28%
    uint256 public constant EPIC_CHANCE = 14;        // 14%
    uint256 public constant LEGENDARY_CHANCE = 6;    // 6%
    uint256 public constant MYTHIC_CHANCE = 2;       // 2%

    // ============ State ============
    uint256 private _nextTokenId;
    address public gameContract;

    struct FishInfo {
        Rarity rarity;
        uint256 mintedAt;
        uint256 lastDustCollectedAt;
    }

    mapping(uint256 => FishInfo) public fish;

    // ============ Events ============
    event FishMinted(address indexed owner, uint256 indexed tokenId, Rarity rarity);
    event SpawnDustCollected(address indexed owner, uint256 indexed tokenId, uint256 amount);

    // ============ Modifiers ============
    modifier onlyGameContract() {
        require(msg.sender == gameContract, "Only game contract");
        _;
    }

    // ============ Constructor ============
    constructor() ERC721("FryReef Fish", "FRYFISH") Ownable(msg.sender) {}

    // ============ Admin ============

    /**
     * @notice Set the game contract address
     */
    function setGameContract(address _gameContract) external onlyOwner {
        gameContract = _gameContract;
    }

    // ============ Minting ============

    /**
     * @notice Mint a new fish with random rarity
     * @param _to Address to mint to
     * @return tokenId The minted token ID
     */
    function mint(address _to) external onlyGameContract returns (uint256) {
        uint256 tokenId = _nextTokenId++;
        Rarity rarity = _determineRarity(tokenId, _to);
        
        _safeMint(_to, tokenId);

        fish[tokenId] = FishInfo({
            rarity: rarity,
            mintedAt: block.timestamp,
            lastDustCollectedAt: block.timestamp
        });

        emit FishMinted(_to, tokenId, rarity);
        return tokenId;
    }

    /**
     * @notice Mint a new fish with specified rarity (for merge)
     * @param _to Address to mint to
     * @param _rarity The rarity of the fish to mint
     * @return tokenId The minted token ID
     */
    function mergeMint(address _to, Rarity _rarity) external onlyGameContract returns (uint256) {
        uint256 tokenId = _nextTokenId++;
        
        _safeMint(_to, tokenId);

        fish[tokenId] = FishInfo({
            rarity: _rarity,
            mintedAt: block.timestamp,
            lastDustCollectedAt: block.timestamp
        });

        emit FishMinted(_to, tokenId, _rarity);
        return tokenId;
    }

    /**
     * @notice Burn a fish (for merge)
     * @param _tokenId The fish token ID to burn
     */
    function burn(uint256 _tokenId) external onlyGameContract {
        require(_exists(_tokenId), "Fish does not exist");
        _burn(_tokenId);
        delete fish[_tokenId];
    }

    // ============ Spawn Dust ============

    /**
     * @notice Get Spawn Dust production rate per day for a rarity
     */
    function getDustPerDay(Rarity _rarity) public pure returns (uint256) {
        if (_rarity == Rarity.Common) return COMMON_DUST_PER_DAY;
        if (_rarity == Rarity.Rare) return RARE_DUST_PER_DAY;
        if (_rarity == Rarity.Epic) return EPIC_DUST_PER_DAY;
        if (_rarity == Rarity.Legendary) return LEGENDARY_DUST_PER_DAY;
        if (_rarity == Rarity.Mythic) return MYTHIC_DUST_PER_DAY;
        return 0;
    }

    /**
     * @notice Get pending Spawn Dust for a single fish
     * @param _tokenId The fish token ID
     */
    function getPendingDustForFish(uint256 _tokenId) public view returns (uint256) {
        require(_exists(_tokenId), "Fish does not exist");
        FishInfo storage fishInfo = fish[_tokenId];
        
        uint256 timeElapsed = block.timestamp - fishInfo.lastDustCollectedAt;
        uint256 dustPerDay = getDustPerDay(fishInfo.rarity);
        
        // Calculate dust: (dustPerDay * timeElapsed) / 1 day
        return (dustPerDay * timeElapsed) / 1 days;
    }

    /**
     * @notice Get total pending Spawn Dust for all fish owned by user
     * @param _owner The owner address
     */
    function getPendingSpawnDust(address _owner) external view returns (uint256) {
        uint256 totalDust = 0;
        uint256 balance = balanceOf(_owner);
        
        for (uint256 i = 0; i < balance; i++) {
            uint256 tokenId = tokenOfOwnerByIndex(_owner, i);
            totalDust += getPendingDustForFish(tokenId);
        }
        
        return totalDust;
    }

    /**
     * @notice Collect Spawn Dust from all fish owned by user
     * @param _owner The owner address
     * @return totalDust Total dust collected
     */
    function collectAllSpawnDust(address _owner) external onlyGameContract returns (uint256) {
        uint256 totalDust = 0;
        uint256 balance = balanceOf(_owner);
        
        for (uint256 i = 0; i < balance; i++) {
            uint256 tokenId = tokenOfOwnerByIndex(_owner, i);
            uint256 dust = getPendingDustForFish(tokenId);
            
            if (dust > 0) {
                fish[tokenId].lastDustCollectedAt = block.timestamp;
                totalDust += dust;
                emit SpawnDustCollected(_owner, tokenId, dust);
            }
        }
        
        return totalDust;
    }

    // ============ View Functions ============

    /**
     * @notice Get fish info
     * @param _tokenId The fish token ID
     */
    function getFishInfo(uint256 _tokenId) external view returns (FishInfo memory) {
        require(_exists(_tokenId), "Fish does not exist");
        return fish[_tokenId];
    }

    /**
     * @notice Get all fish owned by address
     * @param _owner The owner address
     */
    function getFishByOwner(address _owner) external view returns (uint256[] memory) {
        uint256 balance = balanceOf(_owner);
        uint256[] memory tokenIds = new uint256[](balance);
        
        for (uint256 i = 0; i < balance; i++) {
            tokenIds[i] = tokenOfOwnerByIndex(_owner, i);
        }
        
        return tokenIds;
    }

    // ============ Internal ============

    /**
     * @notice Determine rarity based on pseudo-random number
     * @dev Uses block data and token info for randomness (not secure for high-value)
     */
    function _determineRarity(uint256 _tokenId, address _to) internal view returns (Rarity) {
        uint256 random = uint256(keccak256(abi.encodePacked(
            block.timestamp,
            block.prevrandao,
            _tokenId,
            _to,
            _nextTokenId
        ))) % 100;

        // Common: 0-49 (50%)
        if (random < COMMON_CHANCE) return Rarity.Common;
        // Rare: 50-77 (28%)
        if (random < COMMON_CHANCE + RARE_CHANCE) return Rarity.Rare;
        // Epic: 78-91 (14%)
        if (random < COMMON_CHANCE + RARE_CHANCE + EPIC_CHANCE) return Rarity.Epic;
        // Legendary: 92-97 (6%)
        if (random < COMMON_CHANCE + RARE_CHANCE + EPIC_CHANCE + LEGENDARY_CHANCE) return Rarity.Legendary;
        // Mythic: 98-99 (2%)
        return Rarity.Mythic;
    }

    function _exists(uint256 tokenId) internal view returns (bool) {
        return _ownerOf(tokenId) != address(0);
    }

    // ============ Overrides ============

    function _update(address to, uint256 tokenId, address auth)
        internal
        override(ERC721, ERC721Enumerable)
        returns (address)
    {
        return super._update(to, tokenId, auth);
    }

    function _increaseBalance(address account, uint128 value)
        internal
        override(ERC721, ERC721Enumerable)
    {
        super._increaseBalance(account, value);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721Enumerable)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

","keccak256":"0xd02fffadd9cd0efdc95a7460a3eb0385f0f3f259a6b319fef081242ea86346a9","license":"MIT"},"contracts/FryReef.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./EggNFT.sol";
import "./FishNFT.sol";

/**
 * @title FryReef
 * @notice Main game contract: check-in, starter pack, resources
 * @dev Manages Pearl Shards, Spawn Dust, daily check-ins, and starter pack
 */
contract FryReef {
    // ============ Contracts ============
    EggNFT public eggNFT;
    FishNFT public fishNFT;

    // ============ Constants ============
    uint256 public constant STREAK_FOR_REWARD = 7;
    uint256 public constant PEARL_SHARD_REWARD = 1;
    uint256 public constant STARTER_PACK_EGGS = 1;
    uint256 public constant STARTER_PACK_PEARL_SHARDS = 2;
    uint256 public constant STARTER_PACK_SPAWN_DUST = 50;
    uint256 public constant INCUBATION_DURATION = 1 days;
    uint256 public constant INCUBATION_COST = 1; // Pearl Shards
    uint256 public constant EGG_LAYING_COST = 100; // Spawn Dust
    
    // Merge costs (Spawn Dust)
    uint256 public constant MERGE_COMMON_COST = 50;
    uint256 public constant MERGE_RARE_COST = 100;
    uint256 public constant MERGE_EPIC_COST = 200;
    uint256 public constant MERGE_LEGENDARY_COST = 400;

    // ============ State ============
    struct UserInfo {
        uint256 lastCheckIn;
        uint256 currentStreak;
        uint256 totalCheckIns;
        uint256 pearlShards;
        uint256 spawnDust;
        bool starterPackClaimed;
    }

    mapping(address => UserInfo) public users;

    // ============ Events ============
    event CheckedIn(address indexed user, uint256 streak, uint256 totalCheckIns);
    event StreakReward(address indexed user, uint256 pearlShards);
    event StarterPackClaimed(address indexed user, uint256 eggId, uint256 pearlShards, uint256 spawnDust);
    event ResourcesUpdated(address indexed user, uint256 pearlShards, uint256 spawnDust);
    event FishMerged(address indexed user, uint256 fishId1, uint256 fishId2, uint256 newFishId, FishNFT.Rarity newRarity, uint256 pearlShardsReward, uint256 eggsReward);

    // ============ Constructor ============
    constructor(address _eggNFT, address _fishNFT) {
        eggNFT = EggNFT(_eggNFT);
        fishNFT = FishNFT(_fishNFT);
    }

    // ============ Starter Pack ============
    
    /**
     * @notice Claim starter pack (first time only)
     * @dev Gives 1 egg + 2 Pearl Shards
     */
    function claimStarterPack() external {
        UserInfo storage user = users[msg.sender];
        require(!user.starterPackClaimed, "Starter pack already claimed");

        user.starterPackClaimed = true;
        user.pearlShards += STARTER_PACK_PEARL_SHARDS;
        user.spawnDust += STARTER_PACK_SPAWN_DUST;

        // Mint first egg
        uint256 eggId = eggNFT.mint(msg.sender);

        emit StarterPackClaimed(msg.sender, eggId, STARTER_PACK_PEARL_SHARDS, STARTER_PACK_SPAWN_DUST);
        emit ResourcesUpdated(msg.sender, user.pearlShards, user.spawnDust);
    }

    /**
     * @notice Check if user has claimed starter pack
     */
    function hasClaimedStarterPack(address _user) external view returns (bool) {
        return users[_user].starterPackClaimed;
    }

    // ============ Daily Check-in ============

    /**
     * @notice Daily check-in
     * @dev Awards 1 Pearl Shard every 7 consecutive days
     */
    function checkIn() external {
        UserInfo storage user = users[msg.sender];

        uint256 today = _getDayStart(block.timestamp);
        uint256 lastCheckInDay = _getDayStart(user.lastCheckIn);
        uint256 yesterday = today - 1 days;

        require(today > lastCheckInDay, "Already checked in today");

        // Check if streak continues or resets
        if (lastCheckInDay == yesterday) {
            // Consecutive day - continue streak
            user.currentStreak += 1;
        } else {
            // Streak broken - reset to 1
            user.currentStreak = 1;
        }

        user.lastCheckIn = block.timestamp;
        user.totalCheckIns += 1;

        emit CheckedIn(msg.sender, user.currentStreak, user.totalCheckIns);

        // Award Pearl Shard every 7 days
        if (user.currentStreak >= STREAK_FOR_REWARD && user.currentStreak % STREAK_FOR_REWARD == 0) {
            user.pearlShards += PEARL_SHARD_REWARD;
            emit StreakReward(msg.sender, PEARL_SHARD_REWARD);
            emit ResourcesUpdated(msg.sender, user.pearlShards, user.spawnDust);
        }
    }

    /**
     * @notice Check if user has checked in today
     */
    function hasCheckedInToday(address _user) external view returns (bool) {
        uint256 today = _getDayStart(block.timestamp);
        uint256 lastCheckInDay = _getDayStart(users[_user].lastCheckIn);
        return today == lastCheckInDay && users[_user].lastCheckIn > 0;
    }

    // ============ Incubation (Egg → Fish) ============

    /**
     * @notice Start incubating an egg
     * @param _eggId The egg token ID to incubate
     */
    function startIncubation(uint256 _eggId) external {
        UserInfo storage user = users[msg.sender];
        require(user.pearlShards >= INCUBATION_COST, "Not enough Pearl Shards");
        require(eggNFT.ownerOf(_eggId) == msg.sender, "Not egg owner");

        user.pearlShards -= INCUBATION_COST;
        eggNFT.startIncubation(_eggId);

        emit ResourcesUpdated(msg.sender, user.pearlShards, user.spawnDust);
    }

    /**
     * @notice Hatch an incubated egg into a fish
     * @param _eggId The egg token ID to hatch
     */
    function hatchEgg(uint256 _eggId) external {
        require(eggNFT.ownerOf(_eggId) == msg.sender, "Not egg owner");
        require(eggNFT.canHatch(_eggId), "Cannot hatch yet");

        // Burn egg
        eggNFT.burn(_eggId);

        // Mint fish with random rarity
        fishNFT.mint(msg.sender);
    }

    // ============ Egg Laying (Fish → Egg) ============

    /**
     * @notice Lay a new egg from a fish
     * @param _fishId The fish token ID
     */
    function layEgg(uint256 _fishId) external {
        UserInfo storage user = users[msg.sender];
        require(user.spawnDust >= EGG_LAYING_COST, "Not enough Spawn Dust");
        require(fishNFT.ownerOf(_fishId) == msg.sender, "Not fish owner");

        user.spawnDust -= EGG_LAYING_COST;
        eggNFT.mint(msg.sender);

        emit ResourcesUpdated(msg.sender, user.pearlShards, user.spawnDust);
    }

    // ============ Spawn Dust Collection ============

    /**
     * @notice Collect Spawn Dust from all owned fish
     */
    function collectSpawnDust() external {
        UserInfo storage user = users[msg.sender];
        
        uint256 totalDust = fishNFT.collectAllSpawnDust(msg.sender);
        user.spawnDust += totalDust;

        emit ResourcesUpdated(msg.sender, user.pearlShards, user.spawnDust);
    }

    /**
     * @notice Get pending Spawn Dust for a user
     */
    function getPendingSpawnDust(address _user) external view returns (uint256) {
        return fishNFT.getPendingSpawnDust(_user);
    }

    // ============ Merge (Fish → Fish) ============

    /**
     * @notice Merge two fish of the same rarity into a fish of the next rarity
     * @param _fishId1 First fish token ID
     * @param _fishId2 Second fish token ID
     */
    function mergeFish(uint256 _fishId1, uint256 _fishId2) external {
        UserInfo storage user = users[msg.sender];
        
        // Check ownership
        require(fishNFT.ownerOf(_fishId1) == msg.sender, "Not fish owner");
        require(fishNFT.ownerOf(_fishId2) == msg.sender, "Not fish owner");
        require(_fishId1 != _fishId2, "Cannot merge same fish");
        
        // Get fish info
        FishNFT.FishInfo memory fish1 = fishNFT.getFishInfo(_fishId1);
        FishNFT.FishInfo memory fish2 = fishNFT.getFishInfo(_fishId2);
        
        // Check same rarity
        require(fish1.rarity == fish2.rarity, "Fish must be same rarity");
        
        // Check rarity is not Mythic (max rarity)
        require(fish1.rarity != FishNFT.Rarity.Mythic, "Cannot merge Mythic");
        
        // Determine merge cost and rewards
        uint256 mergeCost;
        uint256 pearlShardsReward;
        uint256 eggsReward;
        FishNFT.Rarity newRarity;
        
        if (fish1.rarity == FishNFT.Rarity.Common) {
            mergeCost = MERGE_COMMON_COST;
            pearlShardsReward = 1;
            eggsReward = 0;
            newRarity = FishNFT.Rarity.Rare;
        } else if (fish1.rarity == FishNFT.Rarity.Rare) {
            mergeCost = MERGE_RARE_COST;
            pearlShardsReward = 1;
            eggsReward = 1;
            newRarity = FishNFT.Rarity.Epic;
        } else if (fish1.rarity == FishNFT.Rarity.Epic) {
            mergeCost = MERGE_EPIC_COST;
            pearlShardsReward = 2;
            eggsReward = 1;
            newRarity = FishNFT.Rarity.Legendary;
        } else if (fish1.rarity == FishNFT.Rarity.Legendary) {
            mergeCost = MERGE_LEGENDARY_COST;
            pearlShardsReward = 3;
            eggsReward = 2;
            newRarity = FishNFT.Rarity.Mythic;
        } else {
            revert("Invalid rarity for merge");
        }
        
        // Check user has enough Spawn Dust
        require(user.spawnDust >= mergeCost, "Not enough Spawn Dust");
        
        // Burn both fish
        fishNFT.burn(_fishId1);
        fishNFT.burn(_fishId2);
        
        // Deduct Spawn Dust
        user.spawnDust -= mergeCost;
        
        // Add Pearl Shards reward
        user.pearlShards += pearlShardsReward;
        
        // Mint new fish with next rarity
        uint256 newFishId = fishNFT.mergeMint(msg.sender, newRarity);
        
        // Mint eggs reward
        for (uint256 i = 0; i < eggsReward; i++) {
            eggNFT.mint(msg.sender);
        }
        
        emit FishMerged(msg.sender, _fishId1, _fishId2, newFishId, newRarity, pearlShardsReward, eggsReward);
        emit ResourcesUpdated(msg.sender, user.pearlShards, user.spawnDust);
    }

    // ============ View Functions ============

    /**
     * @notice Get user info
     */
    function getUserInfo(address _user) external view returns (UserInfo memory) {
        return users[_user];
    }

    /**
     * @notice Get user resources
     */
    function getResources(address _user) external view returns (uint256 pearlShards, uint256 spawnDust) {
        UserInfo storage user = users[_user];
        return (user.pearlShards, user.spawnDust);
    }

    // ============ Internal ============

    function _getDayStart(uint256 timestamp) internal pure returns (uint256) {
        return (timestamp / 1 days) * 1 days;
    }
}

